package tv.casa.launcher.check;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;

/** Focused visual regression. No video, network download, firmware or native image changes. */
final class VisualSuite {
    static void invoke(Object object,String name)throws Exception{Method method=object.getClass().getDeclaredMethod(name);method.setAccessible(true);method.invoke(object);}
    static void capture(Checks q,String name)throws Exception{Thread.sleep(250);Bitmap image=q.getUiAutomation().takeScreenshot();q.check(image!=null,"screenshot unavailable");File dir=new File(q.getTargetContext().getExternalFilesDir(null),"visual-qa");dir.mkdirs();try(FileOutputStream output=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,output);}image.recycle();}
    static void sequence(Checks q,Activity main)throws Exception{
        q.ui(()->invoke(main,"showLibrary"));q.waitForIdleSync();Thread.sleep(400);q.ui(()->invoke(main,"closeLibrary"));q.waitForIdleSync();Thread.sleep(250);
        q.ui(()->invoke(main,"showSettings"));q.waitForIdleSync();Thread.sleep(400);q.ui(()->invoke(main,"closePanel"));q.waitForIdleSync();Thread.sleep(250);
        for(int i=0;i<6;i++){final int index=i;q.ui(()->{ArrayList<View> views=(ArrayList<View>)q.field(main,"favoritesViews");views.get(Math.min(index,views.size()-1)).requestFocus();});Thread.sleep(220);}
    }
    static String shell(Checks q,String command)throws Exception{try(ParcelFileDescriptor descriptor=q.getUiAutomation().executeShellCommand(command);InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(descriptor)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[2048];int read;while((read=in.read(bytes))!=-1)out.write(bytes,0,read);return out.toString("UTF-8");}}
    static void benchmark(Checks q)throws Exception{Activity main=q.open("MainActivity",false);String original=(String)q.onUi(main,"lastFocus");try{sequence(q,main);sequence(q,main);shell(q,"dumpsys gfxinfo tv.casa.launcher reset");sequence(q,main);String data=shell(q,"dumpsys gfxinfo tv.casa.launcher");StringBuilder summary=new StringBuilder();for(String line:data.split("\n"))if(line.contains("Total frames")||line.contains("Janky frames")||line.contains("percentile"))summary.append(line).append('\n');q.passed("PASS: same-sequence warm drawing sample after two warmups\n"+summary);}finally{q.ui(()->q.set(main,"lastFocus",original));q.close(main);}}
    static void surfaces(Checks q)throws Exception{Activity gallery=q.open("GalleryActivity",false);try{q.waitFor("gallery ready",()->!((Boolean)q.onUi(gallery,"loading")),5000);q.ui(()->{Button button=(Button)q.field(gallery,"download");button.setEnabled(false);q.check(button.getCurrentTextColor()==0xFF7C8793,"disabled text token missing");button.setEnabled(true);q.check(button.getCurrentTextColor()==0xFFF5F7FA,"normal text token missing");});capture(q,"gallery");}finally{q.close(gallery);}q.passed("PASS: normal and disabled native text states use shared palette");}
    static View description(View root,String prefix){CharSequence value=root.getContentDescription();if(value!=null&&value.toString().startsWith(prefix))return root;if(root instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)root).getChildCount();i++){View found=description(((android.view.ViewGroup)root).getChildAt(i),prefix);if(found!=null)return found;}return null;}
    static void features(Checks q)throws Exception{
        Context context=q.getTargetContext();SharedPreferences prefs=context.getSharedPreferences("MainActivity",0);Map<String,?> original=new HashMap<>(prefs.getAll());Activity main=q.open("MainActivity",false);String focus=(String)q.onUi(main,"lastFocus");
        try{
            q.ui(()->invoke(main,"showPresets"));q.waitForIdleSync();q.ui(()->{Dialog dialog=(Dialog)q.field(main,"activeDialog");q.check(dialog!=null&&dialog.isShowing(),"preset picker absent");q.check(dialog.getCurrentFocus()!=null,"picker focus absent");});capture(q,"preset-picker");q.ui(()->{Dialog picker=(Dialog)q.field(main,"activeDialog");boolean wasClassic=prefs.getString("preset","modern").equals("classic");View card=description(picker.getWindow().getDecorView(),wasClassic?"Moderno.":"Clásico.");q.check(card!=null,"picker action missing");card.performClick();q.check(prefs.getString("preset","").equals(wasClassic?"modern":"classic"),"preset action not applied");});q.waitForIdleSync();
            q.ui(()->invoke(main,"showLibrary"));Object library=q.onUi(main,"library");q.waitFor("local index",()->(Boolean)q.onUi(library,"indexReady"),7000);q.waitForIdleSync();capture(q,"library-tools");
            q.ui(()->((View)q.field(library,"search")).performClick());q.waitForIdleSync();capture(q,"library-query-dialog");q.ui(()->{AlertDialog editor=(AlertDialog)q.field(library,"editor");EditText input=(EditText)editor.getWindow().getDecorView().findViewWithTag("library-query");input.setText("YouTube");editor.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});q.waitForIdleSync();q.ui(()->{ArrayList<String> results=(ArrayList<String>)q.field(library,"packages");q.check(results.contains("com.google.android.youtube.tv")&&results.size()<((ArrayList<?>)q.field(library,"source")).size(),"search did not narrow installed YouTube variants");});capture(q,"library-search");
            q.ui(()->{q.set(library,"query","");q.set(library,"onlyFavorites",true);invoke(library,"applyFilter");Set<String> favorites=new HashSet<>(Arrays.asList(prefs.getString("favorites","com.netflix.ninja,com.google.android.youtube.tv,com.amazon.amazonvideo.livingroom,com.disney.disneyplus,com.wbd.stream,com.spotify.tv.android").split(",")));for(String pkg:(ArrayList<String>)q.field(library,"packages"))q.check(favorites.contains(pkg),"favorite filter leaked an app");});capture(q,"library-favorites");
            q.ui(()->{q.set(library,"query","__velira_no_result__");invoke(library,"applyFilter");q.check(((GridView)q.field(library,"grid")).getCount()==0,"empty query has results");q.check(((View)q.field(library,"search")).hasFocus(),"empty query loses toolbar focus");});capture(q,"library-empty");
            for(int columns:new int[]{4,5,6}){q.ui(()->{q.set(library,"query","");q.set(library,"onlyFavorites",false);((View)q.field(library,"density")).performClick();AlertDialog chooser=(AlertDialog)q.field(library,"densityDialog");ListView choices=chooser.getListView();choices.performItemClick(choices.getChildAt(columns-4),columns-4,columns-4);});q.waitFor("measured grid density",()->((GridView)q.onUi(library,"grid")).getNumColumns()==columns,1500);q.waitForIdleSync();if(columns==4)capture(q,"library-large");}
            q.ui(()->invoke(main,"closeLibrary"));q.ui(()->invoke(main,"showLibrary"));q.waitForIdleSync();q.ui(()->q.check(((GridView)q.field(library,"grid")).getNumColumns()==6,"density lost on reopen"));
            q.passed("PASS: native preset picker, real local search, favorites, empty focus and 4/5/6-column density on TV");
        }finally{q.ui(()->{SharedPreferences.Editor edit=prefs.edit();if(original.containsKey("libraryColumns"))edit.putInt("libraryColumns",(Integer)original.get("libraryColumns"));else edit.remove("libraryColumns");if(original.containsKey("preset"))edit.putString("preset",(String)original.get("preset"));else edit.remove("preset");edit.commit();q.set(main,"lastFocus",focus);invoke(main,"rebuildHome");});q.close(main);}
    }
    static void run(Checks q)throws Exception{
        Context c=q.getTargetContext();ClassLoader loader=c.getClassLoader();Class<?> configuration=Class.forName("tv.casa.launcher.Configuration",true,loader);Method read=configuration.getDeclaredMethod("read",File.class);read.setAccessible(true);File sample=new File(c.getCacheDir(),"visual-backup-test.json");
        String valid="{\"schema\":1,\"favorites\":[],\"showTitle\":true,\"showClock\":true,\"animateFocus\":true,\"ambientHideClock\":false}";
        try{for(String value:new String[]{valid,valid.replace("[]","[\"a.b\"]"),valid.replace("[]","[\"a.b\",\"a.b\"]"),valid.replace("\"ambientHideClock\":false","\"ambientHideClock\":1"),valid.replace("\"schema\":1","\"schema\":\"1\"")}){try(FileOutputStream out=new FileOutputStream(sample)){out.write(value.getBytes("UTF-8"));}boolean rejected=false;try{read.invoke(null,sample);}catch(InvocationTargetException error){rejected=true;}q.check(rejected==(value.contains("1}")||value.contains("\"schema\":\"1\"")||value.contains("\"a.b\",\"a.b\"")),"backup validation mismatch");}}finally{sample.delete();}
        q.passed("PASS: real JSON backup parser accepts empty/one favorite and rejects duplicates and wrong boolean without restoring user data");
        Activity main=q.open("MainActivity",false);SharedPreferences prefs=c.getSharedPreferences("MainActivity",0);Map<String,?> original=new HashMap<>(prefs.getAll());String beforeFavorites=prefs.getString("favorites",null);String beforeFocus=(String)q.onUi(main,"lastFocus");
        try{
            for(String preset:new String[]{"classic","modern","immersive"}){q.ui(()->{prefs.edit().putString("preset",preset).putString("visualEffects","low").commit();invoke(main,"rebuildHome");});q.waitForIdleSync();q.ui(()->{View root=(View)q.field(main,"root");q.check(root.getWidth()>0&&root.getHeight()>0,"unmeasured root");for(View view:(ArrayList<View>)q.field(main,"favoritesViews")){q.check(view.isFocusable(),"favorite not focusable");view.requestFocus();q.check(view.hasFocus(),"favorite focus lost");}for(View view:(ArrayList<View>)q.field(main,"utilityViews")){int[] position=new int[2];view.getLocationOnScreen(position);q.check(position[1]>=0&&position[1]+view.getHeight()<=root.getHeight(),"utility outside safe screen");}});capture(q,"home-"+preset);}
            q.passed("PASS: three presets lay out and focus on the real display, with utility bars within bounds");
            for(String value:new String[]{"","com.google.android.youtube.tv"}){q.ui(()->{prefs.edit().putString("favorites",value).commit();invoke(main,"rebuildHome");});q.waitForIdleSync();q.ui(()->{ArrayList<View> views=(ArrayList<View>)q.field(main,"favoritesViews");q.check(views.size()==1,"empty/single favorite layout count");views.get(0).requestFocus();q.check(views.get(0).hasFocus(),"empty/single favorite loses focus");});}q.ui(()->{SharedPreferences.Editor edit=prefs.edit();if(beforeFavorites==null)edit.remove("favorites");else edit.putString("favorites",beforeFavorites);edit.commit();invoke(main,"rebuildHome");});

            q.ui(()->invoke(main,"showLibrary"));q.waitForIdleSync();Object library=q.onUi(main,"library");q.waitFor("library loaded",()->!((TextView)q.onUi(library,"count")).getText().toString().contains("Cargando"),5000);
            q.ui(()->{GridView grid=(GridView)q.field(library,"grid");q.check(((View)q.field(library,"retry")).getVisibility()==View.GONE,"library failed to load");q.check(grid.getAdapter().hasStableIds(),"library IDs unstable");q.check(grid.hasFocus()||grid.getCount()==0,"library not focused");});capture(q,"library");q.ui(()->invoke(main,"closeLibrary"));
            q.ui(()->invoke(main,"showSettings"));q.waitForIdleSync();q.ui(()->{Dialog dialog=(Dialog)q.field(main,"activeDialog");q.check(dialog!=null&&dialog.isShowing(),"control panel missing");q.check(dialog.getCurrentFocus()!=null,"control panel has no focus");});capture(q,"settings");q.ui(()->invoke(main,"closePanel"));
            q.check(Objects.equals(beforeFavorites,prefs.getString("favorites",null)),"favorites changed");q.passed("PASS: library/control panel focus and stable IDs preserve favorites");
        }finally{q.ui(()->{SharedPreferences.Editor edit=prefs.edit();for(String key:new String[]{"preset","visualEffects","favorites"}){Object value=original.get(key);if(value==null)edit.remove(key);else edit.putString(key,(String)value);}edit.commit();q.set(main,"lastFocus",beforeFocus);invoke(main,"rebuildHome");});q.close(main);}
        Activity gallery=q.open("GalleryActivity",false);
        try{q.waitFor("gallery snapshot",()->!((Boolean)q.onUi(gallery,"loading")),5000);q.ui(()->{q.set(gallery,"busy",true);q.set(gallery,"task",new FutureTask<Void>(()->null));q.callActivityOnStop(gallery);q.callActivityOnStart(gallery);});q.waitFor("gallery reentry",()->!((Boolean)q.onUi(gallery,"loading")),5000);q.ui(()->q.check(((Button)q.field(gallery,"download")).isEnabled(),"gallery controls stuck"));capture(q,"gallery");}finally{q.close(gallery);}
        q.passed("PASS: gallery cancellation before worker execution recovers controls on same-instance reentry");
        Activity online=q.open("OnlineAmbientActivity",false);try{q.waitFor("catalog snapshot",()->(Boolean)q.onUi(online,"snapshotReady"),5000);capture(q,"collections");}finally{q.close(online);}
        q.passed("PASS: online collections restore a usable local snapshot without a network request");
    }
}
